const LEXIQUE_TERMS = [
  {t:"A/B Test", d:'nom donné en pratique (produit/data) à un test d\'hypothèse appliqué à une expérience : control group vs treatment group. <a href="#test-hypothese">Maths ▸ Test d\'hypothèse</a>'},
  {t:"Accuracy", d:'proportion de prédictions correctes sur l\'ensemble des prédictions. <a href="#ml-metrics-classification">Modélisation ▸ Métriques de classification</a>'},
  {t:"ACF (Autocorrelation Function)", d:'mesure la corrélation entre une Time Series et ses versions décalées (lags) — sert à estimer l\'ordre q d\'un processus MA. <a href="#ts-autocorrelation">Modélisation ▸ Modèles ▸ Time Series ▸ Autocorrélation (ACF &amp; PACF)</a>'},
  {t:"AdaBoost", d:'boosting qui repondère les observations mal classées à chaque itération, pour que le weak learner suivant s\'y concentre davantage. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Adam", d:'optimizer de réseau de neurones combinant Momentum et RMSProp — le choix par défaut pour démarrer un entraînement Keras. <a href="#dl-optimizer-choice">Modélisation ▸ Choisir un optimizer</a>'},
  {t:"ADF (Augmented Dickey-Fuller)", d:'test de stationnarité d\'une Time Series : p-value proche de 0 (< 0.05) → série stationnaire. <a href="#ts-stationarity">Modélisation ▸ Stationnarité &amp; test ADF</a>'},
  {t:"Agent (LLM)", d:'utilise un LLM pour prendre des actions vers un objectif (boucle Observe → Think → Act → Repeat), typiquement avec des outils (Tool Calling) et de la mémoire. <a href="#dl-agents">Industrialisation ▸ Agents LLM — de répondeur à exécutant</a>'},
  {t:"Agent (RL)", d:'le décideur qui interagit avec un environnement — observe un état, choisit une action, reçoit une récompense, et met à jour sa stratégie. <a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>'},
  {t:"Apprentissage non supervisé (Unsupervised Learning)", d:'aucun label fourni — le modèle trouve des structures/patterns dans les données seules (ex: clustering, réduction de dimension). <a href="#intro-overview">Modélisation ▸ Qu\'est-ce que la Modélisation</a>'},
  {t:"Apprentissage semi-supervisé (Semi-supervised Learning)", d:'un petit nombre d\'exemples labellisés + beaucoup de données non labellisées — utile quand labelliser coûte cher. <a href="#intro-overview">Modélisation ▸ Qu\'est-ce que la Modélisation</a>'},
  {t:"Apprentissage supervisé (Supervised Learning)", d:'chaque exemple d\'entraînement a une bonne réponse connue (label) — le modèle apprend à la reproduire (ex: régression, classification). <a href="#intro-overview">Modélisation ▸ Qu\'est-ce que la Modélisation</a>'},
  {t:"AR (AutoRegressive)", d:'modèle de Time Series qui régresse Y sur ses propres valeurs passées — un choc se propage loin dans le futur. <a href="#ts-ar-ma">Modélisation ▸ AR &amp; MA</a>'},
  {t:"Arbre de décision (Decision Tree)", d:'modèle hiérarchique qui sépare les données par une suite de décisions binaires (feature, seuil), en minimisant le Gini Index à chaque coupure. <a href="#ml-decision-tree">Modélisation ▸ Arbre de décision</a>'},
  {t:"ARIMA", d:'modèle de Time Series combinant AutoRegressive (AR), Integrated (differencing) et Moving Average (MA), noté ARIMA(p,d,q). <a href="#ts-arima">Modélisation ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"ARMA", d:'combine AR et MA : modélise Y à la fois par ses valeurs passées et par ses erreurs passées. <a href="#ts-arima">Modélisation ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"Attention (Self-Attention)", d:'mécanisme qui permet à chaque token d\'une séquence de "regarder" tous les autres pour calculer sa propre représentation, contextualisée par toute la phrase. <a href="#dl-transformer-attention">Modélisation ▸ Self-Attention — Query, Key, Value</a>'},
  {t:"AUC (Area Under Curve)", d:'aire sous la courbe ROC — mesure la capacité d\'un classifieur à distinguer les classes, indépendamment du seuil choisi. <a href="#ml-roc-auc">Modélisation ▸ ROC-AUC</a>'},
  {t:"Autoencoder", d:'réseau encodeur+décodeur entraîné à reconstruire son propre input via un espace latent compressé — compression, génération, débruitage. <a href="#dl-autoencoder">Modélisation ▸ Autoencoder — encoder, décodeur, espace latent</a>'},
  {t:"AutoTokenizer", d:'classe Hugging Face qui charge le tokenizer EXACTEMENT associé à un modèle pré-entraîné (from_pretrained) — doit toujours correspondre au modèle utilisé, sous peine de tokens incohérents. <a href="#dl-tokenization">Modélisation ▸ Tokenization — du texte aux entiers</a>'},
  {t:"Average Precision (PR-AUC)", d:'aire sous la courbe precision-recall — préférée à l\'AUC-ROC sur un dataset fortement déséquilibré (l\'AUC-ROC reste optimiste, écrasée par les nombreux vrais négatifs). <a href="#ml-roc-auc">Modélisation ▸ ROC-AUC</a>'},
  {t:"Backpropagation (rétropropagation)", d:'calcule le gradient de la Loss d\'un réseau de neurones en repartant de la sortie vers l\'entrée, via la règle de la chaîne — bien plus rapide qu\'un calcul terme à terme. <a href="#dl-backpropagation">Modélisation ▸ Forward &amp; Backward Propagation</a>'},
  {t:"Bag-of-Words (BoW)", d:'représentation vectorielle d\'un texte par comptage des occurrences de chaque mot, sans tenir compte de l\'ordre. <a href="#nlp-vectorizing">Modélisation ▸ Vectorizing</a>'},
  {t:"Bagging (Bootstrap Aggregating)", d:'entraîne plusieurs weak learners EN PARALLÈLE sur des échantillons bootstrap, puis moyenne/vote leurs prédictions — réduit la variance. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Baseline (Baseline Score)", d:'score d\'un modèle trivial (ex: <code>DummyRegressor</code>, <code>DummyClassifier</code>), utilisé comme point de comparaison minimal avant tout modèle réel. <a href="#ml-baseline-concept">Modélisation ▸ Baseline — pourquoi comparer avant de complexifier</a>'},
  {t:"Batch Size", d:'taille du sous-ensemble de données utilisé à chaque mise à jour des paramètres pendant l\'entraînement d\'un réseau de neurones. <a href="#dl-training-loss-optim">Modélisation ▸ Entraînement — loss &amp; optimizer</a>'},
  {t:"Bayes (Théorème de)", d:'relie la probabilité a posteriori d\'une hypothèse à sa probabilité a priori et à la vraisemblance des données observées. <a href="#bayes-naive-bayes">Maths ▸ Théorème de Bayes</a>'},
  {t:"Bellman Equation", d:'formule de mise à jour du Q-Learning — combine la récompense immédiate et la meilleure valeur future estimée, pondérées par learning rate et discount factor. <a href="#dl-rl-q-learning">Modélisation ▸ Q-Learning — apprendre la valeur d\'une action</a>'},
  {t:"BERT (Bidirectional Encoder Representations from Transformers)", d:'Transformer encoder-only pré-entraîné avec attention bidirectionnelle — produit des embeddings contextuels, réutilisables pour classification, NER... <a href="#dl-transformer-families">Modélisation ▸ Encoder-only, Decoder-only, Encoder-Decoder</a>'},
  {t:"Bias (biais)", d:'écart systématique entre les prédictions du modèle et la vraie valeur — un biais élevé signale un modèle trop simple (underfitting). <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"Bias-Variance Tradeoff", d:'compromis fondamental entre un modèle trop simple (bias élevé) et un modèle trop complexe (variance élevée). <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"BLEU (Bilingual Evaluation Understudy)", d:'mesure la proportion de n-grammes du texte généré présents dans la référence (proche d\'une precision), pénalisée si le texte est trop court — utilisé en traduction. <a href="#dl-transformer-evaluation">Modélisation ▸ Évaluer un LLM — BLEU, ROUGE, Perplexité</a>'},
  {t:"Boosting", d:'entraîne les weak learners EN SÉQUENCE, chacun corrigeant les erreurs du précédent — réduit le biais. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Box-Jenkins Method", d:'démarche complète de modélisation ARIMA : stationnariser, lire p/q sur ACF/PACF, fitter, inspecter les résidus, itérer. <a href="#ts-arima">Modélisation ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"Calibration (probabilités)", d:'un modèle est bien calibré si, parmi les prédictions autour de p, environ p% des observations sont réellement positives — l\'accuracy seule ne le garantit pas. <a href="#ml-calibration">Modélisation ▸ Calibration de probabilités</a>'},
  {t:"Chaîne de Markov (Markov Chain)", d:'modélise un système qui change d\'état selon des probabilités de transition fixes — seul l\'état actuel compte (propriété de Markov), pas l\'historique. <a href="#chaines-markov">Maths ▸ Chaînes de Markov</a>'},
  {t:"Checkpointer (LangGraph)", d:'donne une mémoire persistante à un agent — conserve l\'historique de conversation entre plusieurs appels, identifié par un thread_id. <a href="#dl-agents">Industrialisation ▸ Agents LLM — de répondeur à exécutant</a>'},
  {t:"Chunking (RAG)", d:'découpe un document long en morceaux (chunks) avec un léger chevauchement, avant de les embedder — un chunk trop long dépasse la limite d\'entrée de l\'embedder, trop court perd le contexte. <a href="#dl-rag-pipeline">Industrialisation ▸ Pipeline RAG — Embedding, Vector Database, Retrieval</a>'},
  {t:"Classification", d:'tâche de prédiction d\'une catégorie parmi un nombre fini de classes connues (target discrète). <a href="#ml-model-selection">Modélisation ▸ Choisir sa famille de modèle</a>'},
  {t:"CLS (token BERT)", d:'token spécial placé au début de toute séquence pour BERT — son embedding en sortie résume l\'information de la phrase entière, réutilisable comme feature. <a href="#dl-transformer-families">Modélisation ▸ Encoder-only, Decoder-only, Encoder-Decoder</a>'},
  {t:"Clustering", d:'regroupement d\'observations similaires entre elles, sans labels connus au départ. <a href="#ml-model-selection">Modélisation ▸ Choisir sa famille de modèle</a>'},
  {t:"CNN (Convolutional Neural Network)", d:'réseau de neurones spécialisé dans les images, qui empile des couches de convolution (au lieu de couches Dense) pour préserver la structure spatiale de l\'input. <a href="#dl-cnn-why-not-dense">Modélisation ▸ Pourquoi pas un réseau Dense pour les images</a>'},
  {t:"ColumnTransformer", d:'applique en parallèle un traitement différent selon le type de colonne (numérique vs catégorielle) dans une Pipeline. <a href="#ml-workflow-pipeline">Modélisation ▸ Workflow Scikit-learn — avec pipeline (usage réel)</a>'},
  {t:"Concept Drift", d:'la relation entre features et cible change dans le temps (P(y|X) évolue) — un modèle entraîné sur l\'ancienne relation devient FAUX, même si la distribution des features reste stable. <a href="#infra-drift">Industrialisation ▸ Data Drift vs Concept Drift</a>'},
  {t:"Confusion Matrix", d:'tableau croisant prédictions et réalité (TP/TN/FP/FN), base de toutes les métriques de classification. <a href="#ml-metrics-classification">Modélisation ▸ Métriques de classification</a>'},
  {t:"Conv1D", d:'convolution 1D pour du texte — fait glisser le kernel uniquement le long de l\'axe des mots (jamais sur l\'axe de l\'embedding). <a href="#dl-nlp-conv1d">Modélisation ▸ CNN pour du texte — Conv1D</a>'},
  {t:"Conv2DTranspose", d:'couche qui fait l\'inverse d\'une convolution — agrandit la taille spatiale au lieu de la réduire (strides=2 double la taille) ; brique de base d\'un décodeur d\'images. <a href="#dl-conv2d-transpose">Modélisation ▸ Conv2DTranspose — l\'inverse d\'une convolution</a>'},
  {t:"Convolution", d:'opération qui fait glisser un kernel sur une image, en multipliant terme à terme puis en sommant à chaque position, pour produire une feature map. <a href="#dl-cnn-convolution">Modélisation ▸ Convolution — kernel, filtre, feature map</a>'},
  {t:"Corrélation de Pearson", d:'mesure la dépendance LINÉAIRE entre deux variables (r∈[-1,1]) — r=0 n\'implique pas indépendance, seulement l\'absence de lien linéaire. <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"Cosine Similarity", d:'mesure la similarité entre deux vecteurs via l\'angle qui les sépare — métrique la plus utilisée pour la recherche de documents en RAG. <a href="#dl-rag-pipeline">Industrialisation ▸ Pipeline RAG — Embedding, Vector Database, Retrieval</a>'},
  {t:"Cross-Attention", d:'dans le décodeur d\'un Transformer : la query vient du décodeur, mais les keys/values viennent de la sortie de l\'encodeur — relie les deux blocs. <a href="#dl-transformer-architecture">Modélisation ▸ Architecture — Positional Encoding, blocs, masquage</a>'},
  {t:"Cross-Entropy", d:'voir Log Loss.'},
  {t:"Cross-Validation", d:'validation d\'un modèle sur K sous-échantillons du train set, plus robuste qu\'un simple train/test split — pas toujours du K-Fold classique (StratifiedKFold, TimeSeriesSplit, GroupKFold... selon le contexte). <a href="#ml-cross-validation-concept">Modélisation ▸ Cross-Validation</a>'},
  {t:"Curse of Dimensionality (fléau de la dimension)", d:'dégradation de la capacité de généralisation d\'un modèle quand le nombre de features augmente — plus de features nécessite exponentiellement plus de données.'},
  {t:"darts (librairie)", d:'librairie Python de séries temporelles qui unifie de nombreux modèles (naïf, ARIMA, Prophet, TBATS...) sous une même API .fit()/.predict(), avec gestion native des covariables. <a href="#ts-arima">Modélisation ▸ Modèles ▸ Time Series ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"Data Augmentation", d:'génère des variantes des images d\'entraînement (rotation, zoom, miroir...) à la volée, pour plus de diversité sans dupliquer le dataset. <a href="#dl-cnn-data-augmentation">Modélisation ▸ Data Augmentation</a>'},
  {t:"Data Drift", d:'la distribution des features en entrée change dans le temps (nouveaux profils, saisonnalité...) — le modèle reste valide en théorie mais s\'applique à des données différentes de son entraînement. <a href="#infra-drift">Industrialisation ▸ Data Drift vs Concept Drift</a>'},
  {t:"Data Leakage", d:'fuite d\'information du test set (ou du futur) dans l\'entraînement, qui fausse l\'évaluation à la hausse. <a href="#ml-data-leakage-concept">Modélisation ▸ Data Leakage</a>'},
  {t:"Décomposition (Time Series)", d:'sépare une série en Trend + Seasonal + Résidus (additive) ou Trend × Seasonal × Résidus (multiplicative). <a href="#ts-decomposition">Modélisation ▸ Modèles ▸ Time Series ▸ Décomposition</a>'},
  {t:"Deep Learning", d:'réseau de neurones avec BEAUCOUP de layers — pas pertinent sur toute donnée : voir quand le choisir plutôt qu\'un modèle ML classique. <a href="#ml-dl-choice">Modélisation ▸ ML, DL ou RL ?</a>'},
  {t:"Dendrogramme", d:'arbre des fusions successives d\'un clustering hiérarchique — la hauteur d\'une branche = la distance à laquelle deux clusters ont été unis ; couper l\'arbre à une hauteur donnée fixe le nombre de clusters. <a href="#ml-hierarchical-clustering">Modélisation ▸ Clustering Hiérarchique — dendrogramme</a>'},
  {t:"Densité de probabilité (pdf)", d:'hauteur de la courbe d\'une loi continue en un point x — ce n\'est pas directement une probabilité (contrairement à la pmf discrète). <a href="#loi-normale">Maths ▸ Loi normale, LGN &amp; TCL</a>'},
  {t:"Déterminant", d:'scalaire caractérisant une matrice carrée — déterminant = 0 ⇔ matrice NON inversible (colonnes colinéaires), même information que rang < nb de colonnes. <a href="#systeme-lineaire-matriciel">Maths ▸ Résoudre un système linéaire par inversion de matrice</a>'},
  {t:"Discretizing", d:'transformer une variable continue en catégories (ex: prix → Low/High), pour passer d\'une tâche de régression à une tâche de classification. <a href="#ml-discretizing-concept">Modélisation ▸ Discretizing — pourquoi/quand discrétiser</a>'},
  {t:"Distillation (Model Compression)", d:'entraîne un petit modèle "élève" à imiter la distribution de probabilité d\'un grand modèle "professeur" — pas seulement ses labels finaux. <a href="#dl-model-compression">Industrialisation ▸ Compresser un modèle — Quantization &amp; Distillation</a>'},
  {t:"DQN (Deep Q-Network)", d:'remplace la Q-table par un réseau de neurones qui prédit les Q-values à partir d\'un état — passe à l\'échelle sur des espaces d\'états grands ou continus. <a href="#dl-rl-dqn">Modélisation ▸ Deep Q-Network (DQN) — dépasser la Q-table</a>'},
  {t:"Dropout", d:'à chaque itération d\'entraînement, désactive aléatoirement une fraction des neurones d\'une couche — empêche le réseau de sur-dépendre d\'un neurone particulier, améliore la généralisation. <a href="#dl-dropout">Modélisation ▸ Dropout</a>'},
  {t:"Écart interquartile (IQR)", d:'Q3-Q1 ; un point est considéré outlier hors de [Q1-1.5·IQR, Q3+1.5·IQR] — règle utilisée par les moustaches d\'un boxplot. <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"Écart-type", d:'ramène la variance (dispersion autour de la moyenne) dans l\'unité des données ; sur un échantillon, diviser par n-1 (correction de Bessel) plutôt que n. <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"Early Stopping", d:'arrête l\'entraînement d\'un réseau de neurones quand la loss de validation cesse de s\'améliorer — évite l\'overfitting sans fuite de données vers le test set. <a href="#dl-early-stopping">Modélisation ▸ Early Stopping &amp; jeu de validation</a>'},
  {t:"ElasticNet", d:'régularisation combinant Ridge (L2) et Lasso (L1), pondérée par l\'hyperparamètre <code>l1_ratio</code>. <a href="#ml-regularization">Modélisation ▸ Régularisation</a>'},
  {t:"Embedding", d:'représentation d\'un mot par un vecteur dense (30 à 300 dimensions typiquement) — deux mots proches sémantiquement sont proches mathématiquement dans cet espace. <a href="#dl-nlp-word-representation">Modélisation ▸ Représenter les mots — pourquoi un Embedding</a>'},
  {t:"Encodage cyclique (sin/cos)", d:'transforme une variable cyclique (angle, heure, jour de l\'année) en deux colonnes sin/cos, pour que le début et la fin de la période soient bien voisins pour le modèle. <a href="#ml-cyclical-encoding">Modélisation ▸ Encodage cyclique — variables périodiques</a>'},
  {t:"Ensemble Learning", d:'combine plusieurs modèles de base (souvent des arbres de décision) pour obtenir une prédiction plus robuste qu\'un seul modèle. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Epoch", d:'un passage complet sur l\'ensemble du dataset d\'entraînement pendant le fitting d\'un réseau de neurones. <a href="#dl-training-loss-optim">Modélisation ▸ Entraînement — loss &amp; optimizer</a>'},
  {t:"Error Analysis", d:'examen des erreurs individuelles du modèle (sous-groupes, classes, erreurs extrêmes), au-delà d\'un score global unique. <a href="#ml-error-analysis">Modélisation ▸ Error analysis</a>'},
  {t:"Espace latent (Latent Space)", d:'représentation compressée de l\'input produite par l\'encodeur d\'un Autoencoder — dimension bien plus faible que l\'input d\'origine. <a href="#dl-autoencoder">Modélisation ▸ Autoencoder — encoder, décodeur, espace latent</a>'},
  {t:"Espérance (E[X])", d:'moyenne théorique des valeurs d\'une variable aléatoire, pondérée par leur probabilité. <a href="#lois-discretes">Maths ▸ Lois de probabilité discrètes</a>'},
  {t:"Exploration vs Exploitation", d:'compromis en RL entre essayer de nouvelles actions (exploration) et réutiliser les actions déjà connues pour bien performer (exploitation). <a href="#dl-rl-exploration-exploitation">Modélisation ▸ Exploration vs Exploitation, récompenses différées</a>'},
  {t:"F-statistic", d:'teste si un modèle de régression dans son ensemble est significatif (au moins un β≠0) ; Prob(F-statistic) = p-value associée, à regarder avant les coefficients individuels. <a href="#ols-theorie-r2">Maths ▸ Régression linéaire (OLS) — R² et diagnostic</a>'},
  {t:"F1 Score", d:'moyenne harmonique de precision et recall, utile quand aucune des deux n\'est clairement prioritaire. <a href="#ml-metrics-classification">Modélisation ▸ Métriques de classification</a>'},
  {t:"Feature Map", d:'sortie d\'un filtre de convolution appliqué à une image — plus on avance dans les couches d\'un CNN, plus les feature maps sont petites et abstraites. <a href="#dl-cnn-convolution">Modélisation ▸ Convolution — kernel, filtre, feature map</a>'},
  {t:"Feature Scaling", d:'mise à l\'échelle des features numériques (StandardScaler, MinMaxScaler, RobustScaler) avant d\'entraîner un modèle sensible aux échelles. <a href="#ml-scaling-choice">Modélisation ▸ Feature Scaling — quel scaler choisir</a>'},
  {t:"Feature Selection", d:'réduction du nombre de features utilisées par le modèle, pour limiter l\'overfitting et améliorer l\'interprétabilité. <a href="#ml-feature-selection-concept">Modélisation ▸ Feature Selection</a>'},
  {t:"FeatureUnion", d:'applique plusieurs transformers EN PARALLÈLE sur le même jeu de colonnes puis concatène les résultats — utile pour ajouter une feature calculée en plus du preprocessing existant. <a href="#ml-custom-transformer-choice">Modélisation ▸ Transformers personnalisés</a>'},
  {t:"Fenêtrage (Windowing)", d:'transforme une série temporelle brute en paires (séquence d\'entrée, cible) via des fenêtres glissantes — étape de préparation des données avant un RNN. <a href="#dl-rnn-input-shape">Modélisation ▸ Pourquoi un RNN — la dimension temporelle</a>'},
  {t:"FFT (Fast Fourier Transform)", d:'convertit un signal du domaine temporel (amplitude vs. temps) vers le domaine fréquentiel (amplitude vs. fréquence) — fait ressortir les fréquences dominantes d\'un signal complexe (son, etc.), une étape de feature engineering courante avant ML/DL sur de l\'audio. <a href="#fourier-transform">Maths ▸ Transformée de Fourier (FFT)</a>'},
  {t:"Filtre (CNN)", d:'ensemble de kernels (1 par channel de l\'input) dont les sorties sont sommées pour produire UNE feature map — une couche de convolution applique plusieurs filtres en parallèle. <a href="#dl-cnn-convolution">Modélisation ▸ Convolution — kernel, filtre, feature map</a>'},
  {t:"Fine-tuning", d:'repart d\'un modèle pré-entraîné et l\'ajuste pour le spécialiser — moins coûteux qu\'un entraînement from scratch, mais redevient obsolète dès que les données changent. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"from_logits", d:'argument d\'une loss Keras (ex: SparseCategoricalCrossentropy) — à True si la dernière couche renvoie des logits bruts (pas de softmax), pour que la loss applique elle-même la normalisation. <a href="#dl-training-loss-optim">Modélisation ▸ Entraînement — loss &amp; optimizer</a>'},
  {t:"Functional API (Keras)", d:'alternative à Sequential pour construire un modèle : on appelle les couches comme des fonctions (Input → ... → Model(inputs, outputs)) — nécessaire dès qu\'il y a plusieurs entrées/sorties ou des branches parallèles. <a href="#dl-architecture-rules">Modélisation ▸ Construire l\'architecture — règles de choix</a>'},
  {t:"FunctionTransformer", d:'encapsule une transformation STATELESS (qui n\'apprend rien pendant le fit) dans un objet compatible Pipeline, sans écrire de classe. <a href="#ml-custom-transformer-choice">Modélisation ▸ Transformers personnalisés</a>'},
  {t:"Gini Index", d:'mesure l\'impureté d\'un nœud d\'arbre de décision (0 = nœud pur) ; la coupure retenue minimise le Gini pondéré des nœuds enfants. <a href="#ml-decision-tree">Modélisation ▸ Arbre de décision</a>'},
  {t:"GPT (Generative Pre-trained Transformer)", d:'Transformer decoder-only, génère du texte de façon autorégressive (un token à la fois) à partir d\'un prompt. <a href="#dl-transformer-families">Modélisation ▸ Encoder-only, Decoder-only, Encoder-Decoder</a>'},
  {t:"Gradient Boosting", d:'chaque arbre prédit le résidu (l\'erreur) du précédent, au lieu de repondérer comme AdaBoost — généralement plus performant. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Gradient Descent (descente de gradient)", d:'algorithme itératif qui minimise une Loss Function en suivant la pente inverse de son gradient. <a href="#ml-gradient-descent">Modélisation ▸ Gradient Descent</a>'},
  {t:"Grid Search", d:'recherche exhaustive des meilleurs hyperparamètres en testant toutes les combinaisons d\'une grille de valeurs. <a href="#ml-model-tuning">Modélisation ▸ Model Tuning — Grid Search vs Random Search</a>'},
  {t:"Grounding", d:'connecte un LLM à des données externes AU MOMENT DE L\'USAGE (typiquement via RAG), sans ré-entraîner le modèle. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"GRU (Gated Recurrent Unit)", d:'couche récurrente plus légère que le LSTM (moins de paramètres) — entraînement plus rapide, potentiellement moins de données nécessaires. <a href="#dl-rnn-zoology">Modélisation ▸ SimpleRNN, LSTM, GRU</a>'},
  {t:"Guidance Scale", d:'hyperparamètre d\'un modèle de diffusion — contrôle la fidélité de l\'image générée au prompt texte (haut = plus fidèle mais moins naturel/varié). <a href="#dl-diffusion-models">Modélisation ▸ Modèles de diffusion — génération d\'images (Stable Diffusion)</a>'},
  {t:"Gymnasium", d:'librairie (ex-OpenAI Gym) qui fournit des environnements RL prêts à l\'emploi (make, reset, step, close) pour développer et comparer des algorithmes. <a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>'},
  {t:"Hétéroscédasticité", d:'variance des résidus non constante (motif en "entonnoir") — invalide l\'hypothèse de variance constante de l\'OLS ; le R² reste valide, mais p-values et IC des coefficients ne sont plus fiables. <a href="#ols-theorie-r2">Maths ▸ Régression linéaire (OLS) — R² et diagnostic</a>'},
  {t:"Hidden State (état interne)", d:'vecteur maintenu par une couche RNN, mis à jour à chaque pas de temps — résume ce que la séquence a "vu" jusque-là. <a href="#dl-rnn-mechanics">Modélisation ▸ Sous le capot d\'une couche RNN</a>'},
  {t:"Hinge Loss", d:'loss linéaire d\'un SVM en Soft Margin — pénalité proportionnelle à l\'enfoncement d\'un point dans la marge, sans jamais exploser. <a href="#ml-svm-margin">Modélisation ▸ SVM — marge maximale</a>'},
  {t:"History (Keras)", d:'objet retourné par model.fit() — history.history est un dict {"loss": [...], "accuracy": [...]} avec une valeur par epoch, exploitable pour tracer les courbes d\'entraînement. <a href="#dl-early-stopping">Modélisation ▸ Early Stopping &amp; jeu de validation</a>'},
  {t:"Holdout Method", d:'méthode de validation la plus simple : un seul split train/test. <a href="#wf0-split">Modélisation ▸ Workflow ML — Séparer train/test</a>'},
  {t:"Huber Loss", d:'mélange MSE (proche du minimum) et MAE (loin du minimum, peu sensible aux outliers), avec bascule à un seuil δ. <a href="#ml-loss-functions">Modélisation ▸ Loss Functions — régression</a>'},
  {t:"Hugging Face", d:'entreprise/communauté open-source ; sa librairie <code>transformers</code> donne accès en quelques lignes à des modèles pré-entraînés (BERT, GPT, T5...) via des pipelines. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"Hyperparamètre", d:'réglage du modèle choisi manuellement avant l\'entraînement (ex: alpha, K, C) — par opposition aux paramètres (β), appris automatiquement par <code>.fit()</code>.'},
  {t:"Inférence bayésienne", d:'mise à jour d\'une croyance (prior → posterior) à partir de données observées, via le théorème de Bayes. <a href="#bayes-naive-bayes">Maths ▸ Théorème de Bayes</a>'},
  {t:"Intervalle de confiance", d:'plage de valeurs plausibles pour un paramètre estimé, à un niveau de confiance donné (ex: 95%). <a href="#intervalle-confiance">Maths ▸ Intervalle de confiance</a>'},
  {t:"K-Means", d:'algorithme de clustering non supervisé : assigne chaque point au centroïde le plus proche, recalcule les centroïdes, répète jusqu\'à convergence. <a href="#ml-kmeans">Modélisation ▸ K-Means — Clustering</a>'},
  {t:"Keras", d:'API Deep Learning de haut niveau, exécutée au-dessus de TensorFlow, pour définir et entraîner des réseaux de neurones. <a href="#dl-neuron-network">Modélisation ▸ Neurone, Layer, Réseau de neurones</a>'},
  {t:"Kernel (CNN)", d:'petite matrice (ex: 3×3) glissée sur une image pendant une convolution — ses poids sont appris pendant l\'entraînement, comme ceux d\'un neurone Dense. <a href="#dl-cnn-convolution">Modélisation ▸ Convolution — kernel, filtre, feature map</a>'},
  {t:"Kernel Trick", d:'calcule une similarité entre deux points qui simule une transformation vers un espace de dimension supérieure, sans jamais la calculer explicitement. <a href="#ml-svm-kernels">Modélisation ▸ Kernel Trick</a>'},
  {t:"KNN (K-Nearest Neighbors)", d:'modèle non-paramétrique qui prédit à partir des K plus proches voisins d\'un point (moyenne en régression, vote majoritaire en classification). <a href="#ml-knn">Modélisation ▸ KNN — K-Nearest Neighbors</a>'},
  {t:"LangChain", d:'framework Python qui fournit une interface commune pour appeler différents LLM (Google, OpenAI, Anthropic...), plus des briques pour du RAG, des agents, des chaînes de prompts. <a href="#dl-agents">Industrialisation ▸ Agents LLM — de répondeur à exécutant</a>'},
  {t:"Lasso", d:'régularisation L1 — peut ramener des coefficients exactement à 0, ce qui en fait un outil de sélection de features. <a href="#ml-regularization">Modélisation ▸ Régularisation</a>'},
  {t:"LDA (Latent Dirichlet Allocation)", d:'algorithme non supervisé de topic modeling — découvre des thèmes cachés dans un corpus de documents. <a href="#nlp-lda">Modélisation ▸ Modèles ▸ NLP ▸ LDA (Topic Modeling)</a>'},
  {t:"Learning Curve (courbe d'apprentissage)", d:'évolution des scores train/test selon la taille du training set — diagnostique underfitting, overfitting ou besoin de plus de données. <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"Learning Rate (η)", d:'taille du pas de la descente de gradient à chaque itération — trop petit : convergence lente ; trop grand : risque de ne jamais converger. <a href="#ml-gradient-descent">Modélisation ▸ Gradient Descent</a>'},
  {t:"Lemmatisation", d:'ramène chaque mot à sa racine ("running" → "run") pour regrouper les mots par sens plutôt que par forme exacte. <a href="#nlp-preprocessing">Modélisation ▸ Text Preprocessing</a>'},
  {t:"Log Loss (Cross-Entropy)", d:'fonction de perte de la classification binaire, dérivée de la maximisation de la log-vraisemblance — pénalise sévèrement une prédiction confiante et fausse. <a href="#ml-log-loss">Modélisation ▸ Log Loss</a>'},
  {t:"Log-Likelihood (log-vraisemblance)", d:'logarithme de la vraisemblance des données observées sous un modèle — maximisé lors du MLE. <a href="#logit-theorie">Maths ▸ Régression logistique — MLE</a>'},
  {t:"Loi Binomiale", d:'probabilité d\'obtenir exactement k succès sur n essais indépendants de même probabilité p. <a href="#lois-discretes">Maths ▸ Lois de probabilité discrètes</a>'},
  {t:"Loi de Bernoulli", d:'expérience à 2 issues complémentaires (succès/échec), de probabilité p. <a href="#lois-discretes">Maths ▸ Lois de probabilité discrètes</a>'},
  {t:"Loi de Student (T)", d:'loi utilisée pour un test statistique sur petit échantillon (t-test) — plus "lourde aux extrémités" que la loi normale. <a href="#t-test">Maths ▸ t-test</a>'},
  {t:"Loi des probabilités totales", d:'reconstruit P(B) à partir des probabilités conditionnelles par scénario, quand P(B) n\'est pas mesurable directement — c\'est le dénominateur du théorème de Bayes. <a href="#ensembles-base">Maths ▸ Théorie des ensembles &amp; probabilités</a>'},
  {t:"Loi Géométrique", d:'probabilité de réussir pour la première fois au n-ième essai. <a href="#lois-discretes">Maths ▸ Lois de probabilité discrètes</a>'},
  {t:"Lois de De Morgan", d:'réécrit une condition niée sur une combinaison d\'événements (ou un filtre DataFrame) : ¬(A∩B) = ¬A∪¬B et ¬(A∪B) = ¬A∩¬B. <a href="#ensembles-base">Maths ▸ Théorie des ensembles &amp; probabilités</a>'},
  {t:"LoRA (Low-Rank Adaptation)", d:'technique de PEFT — ajoute une petite matrice entraînable EN PARALLÈLE des blocs existants d\'un modèle gelé, au lieu de ré-entraîner tous ses poids. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"Loss Function", d:'fonction que <code>.fit()</code> minimise pour trouver les meilleurs paramètres d\'un modèle — le choix de la Loss définit ce que "meilleur modèle" veut dire. <a href="#ml-fit-hood">Modélisation ▸ Que fait .fit() ?</a>'},
  {t:"LSTM (Long Short-Term Memory)", d:'couche récurrente introduite pour corriger le vanishing gradient d\'un SimpleRNN — plus de paramètres, mémoire plus longue. <a href="#dl-rnn-zoology">Modélisation ▸ SimpleRNN, LSTM, GRU</a>'},
  {t:"Machine Learning", d:'modèles statistiques/algorithmiques sur données structurées (régression, arbres, SVM, clustering, PCA...) — par opposition au Deep Learning, réservé aux données non-structurées. <a href="#intro-overview">Modélisation ▸ Qu\'est-ce que la Modélisation</a>'},
  {t:"MAE (Mean Absolute Error)", d:'moyenne des erreurs absolues — pénalise chaque erreur proportionnellement à sa taille. <a href="#ml-metrics-regression">Modélisation ▸ Métriques de régression</a>'},
  {t:"make_scorer", d:'transforme une fonction métrique maison (y_true, y_pred) -> score en un "scorer" sklearn valide, utilisable dans scoring= (cross_validate, GridSearchCV...). <a href="#ml-model-tuning">Modélisation ▸ Model Tuning — Grid Search vs Random Search</a>'},
  {t:"MAP (Maximum a Posteriori)", d:'estimation qui maximise la probabilité a posteriori, combinant la vraisemblance des données et un a priori sur le paramètre.'},
  {t:"Masking (Keras)", d:'couche placée en tête d\'un modèle RNN pour ignorer, pendant l\'entraînement, les pas de temps factices ajoutés par le padding. <a href="#dl-rnn-padding">Modélisation ▸ Séquences de longueurs différentes</a>'},
  {t:"Max Error", d:'borne l\'erreur individuelle la plus grave d\'un modèle de régression — utile quand une seule erreur extrême est inacceptable (ex: sécurité). <a href="#ml-metrics-regression">Modélisation ▸ Métriques de régression</a>'},
  {t:"MCP (Model Context Protocol)", d:'protocole standard (Anthropic) pour exposer un outil/une source de données à N\'IMPORTE QUEL agent compatible, sans code de connexion sur-mesure par paire agent-outil. <a href="#dl-mcp">Industrialisation ▸ MCP (Model Context Protocol) — standardiser l\'accès aux outils</a>'},
  {t:"Médiane", d:'sépare les données triées en deux moitiés égales — contrairement à la moyenne, robuste aux outliers. <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"Minimum local / global", d:'un minimum local minimise une fonction au voisinage d\'un point, sans être forcément le minimum absolu (global) sur tout le domaine — un optimiseur parti d\'un mauvais point de départ peut y rester bloqué si la fonction n\'est pas convexe. <a href="#ml-gradient-descent">Modélisation ▸ Gradient Descent</a>'},
  {t:"MLE (Maximum Likelihood Estimation)", d:'estimation qui maximise la vraisemblance des données observées sous le modèle. <a href="#logit-theorie">Maths ▸ Régression logistique — MLE</a>'},
  {t:"Mode (statistique)", d:'valeur la plus fréquente d\'une distribution — il peut y en avoir plusieurs (distribution bimodale). <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"ModelCheckpoint", d:'callback Keras qui sauvegarde automatiquement le modèle sur disque à chaque amélioration de la métrique surveillée pendant l\'entraînement. <a href="#dl-early-stopping">Modélisation ▸ Early Stopping &amp; jeu de validation</a>'},
  {t:"Modèle de diffusion (Diffusion Model)", d:'génère une image en débruitant progressivement du bruit pur, guidé par un prompt texte — principe derrière Stable Diffusion. <a href="#dl-diffusion-models">Modélisation ▸ Modèles de diffusion — génération d\'images (Stable Diffusion)</a>'},
  {t:"Moyenne", d:'somme des valeurs divisée par leur nombre — notée µ sur toute la population, x̄ sur un échantillon extrait de cette population. <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"MSE (Mean Squared Error)", d:'moyenne des erreurs au carré — pénalise fortement les grosses erreurs, très sensible aux outliers. <a href="#ml-metrics-regression">Modélisation ▸ Métriques de régression</a>'},
  {t:"MSLE (Mean Squared Log Error)", d:'MSE calculé sur le log de la prédiction/target — pénalise l\'erreur RELATIVE plutôt que l\'écart absolu, adapté à une target positive très étalée (ex: prix). <a href="#ml-loss-functions">Modélisation ▸ Loss Functions — régression</a>'},
  {t:"Multi-Agent System", d:'plusieurs agents LLM spécialisés collaborent sur une tâche complexe (ex: recherche, résumé, rédaction) — spécialisation, parallélisme, délégation. <a href="#dl-agents">Industrialisation ▸ Agents LLM — de répondeur à exécutant</a>'},
  {t:"Multi-Head Attention", d:'exécute plusieurs mécanismes d\'attention en parallèle (têtes), chacune spécialisée sur un aspect différent — les sorties sont concaténées. <a href="#dl-transformer-multihead">Modélisation ▸ Multi-Head Attention</a>'},
  {t:"Multicolinéarité", d:'redondance entre plusieurs features, au-delà des simples paires détectées par une matrice de corrélation classique. <a href="#ml-multicollinearity">Maths ▸ Multicolinéarité — VIF</a>'},
  {t:"N-gram", d:'séquence de n mots consécutifs (bigram, trigram...), utilisée en vectorizing pour restaurer une partie du contexte perdu par le Bag-of-Words. <a href="#nlp-vectorizing">Modélisation ▸ Vectorizing</a>'},
  {t:"Naive Bayes", d:'classifieur de texte basé sur le théorème de Bayes, sous l\'hypothèse (naïve) que les mots d\'un document sont conditionnellement indépendants. <a href="#nlp-naive-bayes">Modélisation ▸ Naive Bayes</a>'},
  {t:"NearestNeighbors", d:'version non supervisée de KNN — indexe un jeu de données et renvoie les k plus proches voisins d\'un point, sans classer ni prédire (base d\'un système de recommandation par similarité). <a href="#ml-knn">Modélisation ▸ KNN — K-Nearest Neighbors</a>'},
  {t:"Neurone (Deep Learning)", d:'brique de base d\'un réseau de neurones — une régression linéaire suivie d\'une fonction d\'activation non-linéaire. <a href="#dl-neuron-network">Modélisation ▸ Neurone, Layer, Réseau de neurones</a>'},
  {t:"No Free Lunch Theorem", d:'aucun modèle n\'est optimal pour tous les problèmes — le choix dépend des hypothèses faites sur les données. <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"Non-paramétrique (modèle)", d:'modèle dont le nombre de paramètres appris dépend des données elles-mêmes (ex: KNN, kernel-SVM) — aucune hypothèse a priori sur leur structure. <a href="#ml-model-selection">Modélisation ▸ Choisir sa famille de modèle</a>'},
  {t:"One-Hot Encoding", d:'encodage d\'une variable catégorielle sans ordre en une colonne binaire par catégorie. <a href="#ml-encoding-choice">Modélisation ▸ Encoding — quel encodage choisir</a>'},
  {t:"One-vs-Rest / One-vs-One (OvR / OvO)", d:'stratégies pour étendre un classifieur binaire à k classes — OvR : un modèle par classe vs le reste ; OvO : un modèle par paire de classes. <a href="#ml-multiclass-strategies">Modélisation ▸ Stratégies multiclasse (One-vs-Rest vs One-vs-One)</a>'},
  {t:"Opérations sur les ensembles (Union, Intersection, Complémentaire)", d:'Union : P(A∪B)=P(A)+P(B)-P(A∩B) ; Intersection d\'événements indépendants : P(A∩B)=P(A)·P(B) ; Complémentaire : P(Ā)=1-P(A). <a href="#ensembles-base">Maths ▸ Théorie des ensembles &amp; probabilités</a>'},
  {t:"Overfitting (surapprentissage)", d:'le modèle capte le bruit des données d\'entraînement en plus du signal — score train haut, score test bas. <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"p-value", d:'probabilité d\'observer un résultat au moins aussi extrême que celui obtenu, sous l\'hypothèse nulle. <a href="#test-hypothese">Maths ▸ Test d\'hypothèse</a>'},
  {t:"PACF (Partial Autocorrelation Function)", d:'corrélation entre une Time Series et un lag donné, en retirant l\'effet des lags intermédiaires — sert à estimer l\'ordre p d\'un processus AR. <a href="#ts-autocorrelation">Modélisation ▸ Modèles ▸ Time Series ▸ Autocorrélation (ACF &amp; PACF)</a>'},
  {t:"Padding (CNN)", d:'remplissage à 0 ajouté autour d\'une image avant une convolution — \'same\' garde la feature map à la taille de l\'input, \'valid\' (défaut) laisse la feature map rétrécir. <a href="#dl-cnn-hyperparams">Modélisation ▸ Hyperparamètres de la convolution</a>'},
  {t:"Padding (RNN)", d:'complète les séquences plus courtes que la plus longue du batch avec une valeur factice absente des données réelles, de préférence en fin de séquence (padding=\'post\'). <a href="#dl-rnn-padding">Modélisation ▸ Séquences de longueurs différentes</a>'},
  {t:"Paramétrique (modèle)", d:'modèle à nombre fixe de paramètres, indépendant de n (ex: LinearRegression, LogisticRegression). <a href="#ml-model-selection">Modélisation ▸ Choisir sa famille de modèle</a>'},
  {t:"PCA (Principal Component Analysis)", d:'cherche la meilleure combinaison linéaire des features existantes pour résumer le dataset dans moins de dimensions. <a href="#ml-pca">Modélisation ▸ PCA — Réduction de dimension</a>'},
  {t:"PEFT (Parameter-Efficient Fine-Tuning)", d:'gèle un LLM pré-entraîné et n\'entraîne que quelques couches supplémentaires légères — ex: LoRA. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"Perplexité", d:'mesure à quel point un modèle de langage est "surpris" par les données — probabilité qu\'il assigne à chaque token suivant, utilisée surtout pendant l\'entraînement. <a href="#dl-transformer-evaluation">Modélisation ▸ Évaluer un LLM — BLEU, ROUGE, Perplexité</a>'},
  {t:"Pipeline", d:'enchaînement d\'étapes de preprocessing puis de modélisation en un seul objet Sklearn. <a href="#ml-workflow-pipeline">Modélisation ▸ Workflow Scikit-learn — avec pipeline (usage réel)</a>'},
  {t:"PMF (Probability Mass Function)", d:'probabilité P(X=xᵢ) qu\'une variable aléatoire DISCRÈTE prenne une valeur précise — équivalent discret de la pdf (densité) d\'une variable continue. <a href="#variable-aleatoire">Maths ▸ Variable aléatoire</a>'},
  {t:"Policy (RL)", d:'stratégie de l\'agent — associe à chaque état la ou les actions à prendre, pour maximiser la récompense cumulée sur le long terme. <a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>'},
  {t:"PolynomialFeatures", d:'ajoute les termes polynomiaux et croisés (a², b², a·b...) d\'un feature set — permet à un modèle linéaire de capturer des relations non-linéaires/des interactions. <a href="#ml-svm-kernels">Modélisation ▸ Kernel Trick — rendre les données linéairement séparables</a>'},
  {t:"Pooling (Max/Average)", d:'réduit la taille d\'une feature map sans aucun paramètre entraînable, en gardant le max (MaxPooling, le plus courant) ou la moyenne (AveragePooling) de chaque sous-région. <a href="#dl-cnn-hyperparams">Modélisation ▸ Hyperparamètres de la convolution</a>'},
  {t:"Positional Encoding", d:'ajouté à l\'embedding de chaque token pour réintroduire l\'information de position, perdue quand le Transformer traite toute la séquence en parallèle. <a href="#dl-transformer-architecture">Modélisation ▸ Architecture — Positional Encoding, blocs, masquage</a>'},
  {t:"PPO (Proximal Policy Optimization)", d:'algorithme RL policy-based — ajuste directement la policy (au lieu d\'une Q-table/Q-network), seul choix pour des actions continues, avec un clipping qui limite l\'ampleur de chaque mise à jour. <a href="#dl-rl-dqn">Modélisation ▸ Deep Q-Network (DQN) — dépasser la Q-table</a>'},
  {t:"Precision", d:'fiabilité d\'une prédiction positive — à privilégier quand une fausse alerte coûte cher. <a href="#ml-metrics-classification">Modélisation ▸ Métriques de classification</a>'},
  {t:"Precision-Recall Tradeoff", d:'compromis entre precision et recall selon le seuil de décision choisi. <a href="#ml-choose-metric">Modélisation ▸ Choisir sa métrique</a>'},
  {t:"Probabilité conditionnelle", d:'restreint l\'univers à B, puis regarde la part de A dedans : P(A|B) = P(A∩B)/P(B). <a href="#ensembles-base">Maths ▸ Théorie des ensembles &amp; probabilités</a>'},
  {t:"Prompt Engineering", d:'formuler soigneusement l\'instruction donnée à un LLM (zero-shot, few-shot, exemples...) pour obtenir de meilleurs résultats, sans changer les poids du modèle. <a href="#dl-prompt-engineering">Modélisation ▸ Prompt Engineering — principes</a>'},
  {t:"Prophet (Facebook)", d:'librairie de prévision de séries temporelles, alternative à ARIMA — gère nativement tendance et saisonnalité(s) sans passer par ACF/PACF/differencing, format imposé (colonnes ds/y). <a href="#ts-arima">Modélisation ▸ Modèles ▸ Time Series ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"Pseudo R²", d:'indicateur de qualité d\'ajustement pour la régression logistique, basé sur le rapport des log-vraisemblances. <a href="#logit-theorie">Maths ▸ Régression logistique — MLE</a>'},
  {t:"Puissance (test statistique)", d:'probabilité de détecter un effet réel quand il existe vraiment (1-β) — plus elle est grande, mieux c\'est. <a href="#test-hypothese">Maths ▸ Test d\'hypothèse</a>'},
  {t:"Q-Learning", d:'algorithme RL model-free qui apprend, dans une Q-table, la valeur de chaque paire (état, action), mise à jour via l\'équation de Bellman. <a href="#dl-rl-q-learning">Modélisation ▸ Q-Learning — apprendre la valeur d\'une action</a>'},
  {t:"Q-Value (Q(s,a))", d:'estime à quel point il est bon de prendre l\'action a dans l\'état s — le Q-Learning choisit toujours l\'action de plus haut Q. <a href="#dl-rl-q-learning">Modélisation ▸ Q-Learning — apprendre la valeur d\'une action</a>'},
  {t:"Quantization", d:'remplace les poids d\'un modèle par une précision plus faible (16-bit float, 8-bit int...) — modèle plus petit et plus rapide, perte de précision minime. <a href="#dl-model-compression">Industrialisation ▸ Compresser un modèle — Quantization &amp; Distillation</a>'},
  {t:"Query/Key/Value (Q/K/V)", d:'les 3 vecteurs projetés à partir de chaque token pour calculer l\'attention — query = "que cherche-t-il ?", key = "qui est-il ?", value = "quelle info apporte-t-il ?". <a href="#dl-transformer-attention">Modélisation ▸ Self-Attention — Query, Key, Value</a>'},
  {t:"R² (coefficient de détermination)", d:'proportion de la variance de y expliquée par le modèle. <a href="#ml-metrics-regression">Modélisation ▸ Métriques de régression</a>'},
  {t:"RAG (Retrieval-Augmented Generation)", d:'récupère les documents pertinents pour une question (Information Retrieval) puis les injecte dans le prompt avant génération, au lieu de fine-tuner le modèle. <a href="#dl-rag-why">Industrialisation ▸ Pourquoi le RAG — les limites d\'un LLM figé</a>'},
  {t:"Random Forest", d:'bagging d\'arbres de décision — cas particulier du Bagging optimisé spécifiquement pour les arbres. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Random Search", d:'recherche aléatoire d\'hyperparamètres dans un espace de valeurs, plus scalable que Grid Search sur un grand espace. <a href="#ml-model-tuning">Modélisation ▸ Model Tuning</a>'},
  {t:"Recall", d:'capacité à détecter les occurrences réelles d\'une classe — à privilégier quand rater un positif coûte cher. <a href="#ml-metrics-classification">Modélisation ▸ Métriques de classification</a>'},
  {t:"ReduceLROnPlateau", d:'callback Keras qui réduit le learning rate quand une métrique surveillée stagne pendant plusieurs epochs — alternative/complément à un scheduler fixe. <a href="#dl-early-stopping">Modélisation ▸ Early Stopping &amp; jeu de validation</a>'},
  {t:"return_sequences (Keras)", d:'argument d\'une couche RNN — renvoie la sortie à CHAQUE pas de temps (au lieu du seul dernier état), nécessaire pour prédire une séquence ou empiler un autre RNN. <a href="#dl-rnn-return-sequences">Modélisation ▸ Sortie d\'une couche RNN</a>'},
  {t:"Règle du produit (chain rule, probabilités)", d:'P(A∩B) = P(A|B)·P(B) = P(B|A)·P(A) — reste valable même si A et B ne sont PAS indépendants. <a href="#ensembles-base">Maths ▸ Théorie des ensembles &amp; probabilités</a>'},
  {t:"Régression", d:'tâche de prédiction d\'une quantité continue (target numérique). <a href="#ml-model-selection">Modélisation ▸ Choisir sa famille de modèle</a>'},
  {t:"Régression linéaire (LinearRegression)", d:'modèle de référence en régression — combine linéairement les features, solution exacte en une étape ($\\hat\\beta=(X^\\top X)^{-1}X^\\top y$), aucune régularisation par défaut. <a href="#ml-linear-logistic">Modélisation ▸ Régression linéaire &amp; logistique</a>'},
  {t:"Régression logistique (LogisticRegression)", d:'modèle de référence en classification binaire — sortie = probabilité via la sigmoïde, coefficients estimés par MLE (pas de solution fermée), régularisée L2 PAR DÉFAUT (hyperparamètre C). <a href="#ml-linear-logistic">Modélisation ▸ Régression linéaire &amp; logistique</a>'},
  {t:"Régularisation", d:'pénalité ajoutée à la Loss Function pour limiter la complexité du modèle et réduire l\'overfitting. <a href="#ml-regularization">Modélisation ▸ Régularisation</a>'},
  {t:"Reinforcement Learning", d:'un agent apprend par essai-erreur à maximiser une récompense en interagissant avec un environnement — pas de label, seulement une récompense reçue après une séquence d\'actions. <a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>'},
  {t:"ReLU", d:'fonction d\'activation $f(x)=\\max(0,x)$, choix par défaut pour les couches cachées d\'un réseau de neurones. <a href="#dl-activation">Modélisation ▸ Fonctions d\'activation</a>'},
  {t:"Ridge", d:'régularisation L2 — rétrécit les coefficients vers 0 sans jamais les annuler. <a href="#ml-regularization">Modélisation ▸ Régularisation</a>'},
  {t:"RLHF (Reinforcement Learning from Human Feedback)", d:'fine-tuning dont le signal de récompense vient d\'évaluations humaines — à la base des modèles "chat" grand public. <a href="#dl-llm-adapt">Industrialisation ▸ Adapter un LLM — Training, Fine-tuning, Grounding</a>'},
  {t:"RMSE (Root Mean Squared Error)", d:'racine du MSE — ramène l\'erreur dans l\'unité de la target. <a href="#ml-metrics-regression">Modélisation ▸ Métriques de régression</a>'},
  {t:"RNN (Recurrent Neural Network)", d:'réseau de neurones spécialisé dans les séquences temporelles, qui maintient un état interne mis à jour à chaque pas de temps. <a href="#dl-rnn-input-shape">Modélisation ▸ Pourquoi un RNN — la dimension temporelle</a>'},
  {t:"ROC Curve", d:'trace le compromis recall (TPR) vs taux de faux positifs (FPR) pour tous les seuils possibles. <a href="#ml-roc-auc">Modélisation ▸ ROC-AUC</a>'},
  {t:"ROUGE (Recall-Oriented Understudy for Gisting Evaluation)", d:'mesure la proportion de l\'information de la référence retrouvée dans le texte généré (proche d\'un recall) — utilisé en résumé. <a href="#dl-transformer-evaluation">Modélisation ▸ Évaluer un LLM — BLEU, ROUGE, Perplexité</a>'},
  {t:"SARIMA", d:'extension d\'ARIMA avec 3 hyperparamètres supplémentaires (P,D,Q)[S] pour modéliser la saisonnalité directement. <a href="#ts-arima">Modélisation ▸ ARMA, ARIMA &amp; SARIMA</a>'},
  {t:"Scheduler (Learning Rate)", d:'fait décroître automatiquement le learning rate pendant l\'entraînement (ex: ExponentialDecay) — grands pas au début, petits pas vers la fin. <a href="#dl-hyperparameters">Modélisation ▸ Hyperparamètres — learning rate, batch size, epochs</a>'},
  {t:"Score-z (z-score)", d:'nombre d\'écarts-types séparant une observation de la moyenne — permet de comparer des valeurs mesurées sur des échelles différentes. <a href="#loi-normale">Maths ▸ Loi normale, LGN &amp; TCL</a>'},
  {t:"SGD (Stochastic Gradient Descent)", d:'mini-batch de taille 1 — moins stable qu\'un Gradient Descent classique mais beaucoup plus rapide sur les gros datasets, permet de sortir d\'un minimum local. <a href="#ml-solvers">Modélisation ▸ Variantes de la descente de gradient</a>'},
  {t:"SimpleRNN", d:'couche récurrente la plus simple et la plus rapide à entraîner, mais à mémoire courte (vanishing gradient marqué à travers le temps). <a href="#dl-rnn-zoology">Modélisation ▸ SimpleRNN, LSTM, GRU</a>'},
  {t:"Smoothing (NLP)", d:'ajoute un paramètre α>0 aux fréquences de mots pour éviter les probabilités nulles en Naive Bayes, quand un mot n\'a jamais été vu dans une classe. <a href="#nlp-naive-bayes">Modélisation ▸ Naive Bayes</a>'},
  {t:"SMOTE (Synthetic Minority Oversampling Technique)", d:'génère de nouveaux points synthétiques de la classe minoritaire par interpolation entre plus proches voisins, au lieu de dupliquer des points existants. <a href="#ml-balancing-concept">Modélisation ▸ Balancing</a>'},
  {t:"Soft Margin (SVM)", d:'autorise certains points à être à l\'intérieur de la marge, voire du mauvais côté, moyennant une pénalité (Hinge Loss). <a href="#ml-svm-margin">Modélisation ▸ SVM — marge maximale</a>'},
  {t:"Softmax", d:'fonction d\'activation de la dernière couche en classification multi-classe — transforme k scores en probabilités qui somment à 1. <a href="#dl-activation">Modélisation ▸ Fonctions d\'activation</a>'},
  {t:"Solver", d:'méthode utilisée pour minimiser la Loss Function pendant <code>.fit()</code> — résolution exacte ou itérative (Gradient Descent, Newton...). <a href="#ml-fit-hood">Modélisation ▸ Que fait .fit() ?</a>'},
  {t:"Stable Baselines3 (sb3)", d:'librairie d\'implémentations fiables d\'algorithmes RL (DQN, PPO, A2C...) — entraîner un agent tient en quelques lignes (DQN, .learn(), .predict()). <a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>'},
  {t:"Stacking", d:'entraîne des modèles DIFFÉRENTS qui capturent chacun une structure différente des données, puis agrège leurs prédictions (vote/moyenne, ou modèle final entraîné sur leurs prédictions). <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
  {t:"Stationnarité", d:'propriété d\'une Time Series dont les caractéristiques statistiques (moyenne, variance, autocorrélation) ne dépendent pas du temps. <a href="#ts-stationarity">Modélisation ▸ Stationnarité &amp; test ADF</a>'},
  {t:"Stopwords", d:'mots très fréquents porteurs de peu d\'information ("the", "is"...), souvent retirés en preprocessing NLP — sauf en analyse de sentiment. <a href="#nlp-preprocessing">Modélisation ▸ Text Preprocessing</a>'},
  {t:"Stratify (train_test_split)", d:'répartit chaque classe de y dans les mêmes proportions entre train et test — indispensable sur une target déséquilibrée. <a href="#wf0-split">Modélisation ▸ Workflow ML — Séparer train/test</a>'},
  {t:"Strides (CNN)", d:'pas de déplacement du kernel pendant une convolution — strides=2 saute un pixel sur deux et divise par ~2 la taille de la feature map en sortie. <a href="#dl-cnn-hyperparams">Modélisation ▸ Hyperparamètres de la convolution</a>'},
  {t:"Support Vector Machine (SVM)", d:'modèle qui cherche l\'hyperplan maximisant la marge entre les classes. <a href="#ml-svm-margin">Modélisation ▸ SVM — marge maximale</a>'},
  {t:"Support Vectors", d:'points d\'entraînement situés sur la frontière de la marge d\'un SVM — ce sont eux qui déterminent l\'hyperplan. <a href="#ml-svm-margin">Modélisation ▸ SVM — marge maximale</a>'},
  {t:"Système linéaire (Xθ=y)", d:'système de n équations à n inconnues résolu par inversion de matrice (θ=X⁻¹y) — quand il y a plus d\'observations que d\'inconnues (surdéterminé), plus de solution exacte : c\'est le problème que la régression linéaire (OLS) résout par approximation. <a href="#systeme-lineaire-matriciel">Maths ▸ Résoudre un système linéaire par inversion de matrice</a>'},
  {t:"t-test", d:'test statistique comparant une moyenne observée à une hypothèse, adapté aux petits échantillons. <a href="#t-test">Maths ▸ t-test</a>'},
  {t:"T5 (Text-to-Text Transfer Transformer)", d:'Transformer encoder-decoder qui traite toute tâche NLP comme une transformation texte→texte (traduction, résumé, classification...). <a href="#dl-transformer-families">Modélisation ▸ Encoder-only, Decoder-only, Encoder-Decoder</a>'},
  {t:"Temperature (génération)", d:'contrôle le hasard du choix du prochain token d\'un LLM — basse = déterministe/répétitif, haute = créatif/aléatoire. <a href="#dl-transformer-generation-params">Modélisation ▸ Contrôler la génération — Temperature, Top-k, Top-p</a>'},
  {t:"TensorBoard", d:'interface de suivi/comparaison d\'entraînements en direct, à partir de logs écrits dans un dossier — via un callback Keras (<a href="#dl-early-stopping">Modélisation ▸ Early Stopping &amp; jeu de validation</a>) ou le paramètre tensorboard_log d\'un modèle Stable Baselines3 (<a href="#dl-rl-foundations">Modélisation ▸ Reinforcement Learning — composants &amp; boucle</a>).'},
  {t:"TensorFlow", d:'librairie de calcul sur tensors développée par Google, sur laquelle Keras s\'appuie — à utiliser (fonctions <code>tf.*</code>) à la place de Numpy/Pandas dans toute fonction exécutée à l\'intérieur du graphe Keras. <a href="#dl-tf-ops-required">Modélisation ▸ Pourquoi tf.* et pas Numpy/Pandas</a>'},
  {t:"TextVectorization", d:'couche Keras qui combine Tokenizer + pad_sequences en une seule étape intégrée au modèle — même logique que Normalization pour du numérique. <a href="#dl-tokenization">Modélisation ▸ Tokenization — du texte aux entiers</a>'},
  {t:"Tf-idf", d:'pondère le comptage Bag-of-Words par l\'inverse document frequency, pour donner plus de poids aux mots rares dans le corpus. <a href="#nlp-vectorizing">Modélisation ▸ Vectorizing</a>'},
  {t:"tf.data.Dataset", d:'objet Keras qui charge un gros dataset (ex: images) batch par batch, sans tout mettre en RAM d\'un coup — se passe directement à model.fit(ds, ...). <a href="#dl-tf-ops-required">Modélisation ▸ Pourquoi tf.* et pas Numpy/Pandas dans un modèle Keras</a>'},
  {t:"Théorème Central Limite (TCL)", d:'la moyenne d\'échantillons tend vers une loi normale quand la taille d\'échantillon augmente, quelle que soit la distribution d\'origine. <a href="#loi-normale">Maths ▸ Loi normale, LGN &amp; TCL</a>'},
  {t:"Time Series", d:'suite d\'observations prises à intervalles de temps réguliers — deux objectifs : comprendre (décomposer) ou prévoir (forecaster). <a href="#ts-decomposition">Modélisation ▸ Modèles ▸ Time Series ▸ Décomposition</a>'},
  {t:"Tokenizer (Keras)", d:'construit un dictionnaire mot→entier à partir d\'un corpus (<code>fit_on_texts</code>), puis convertit des phrases en séquences d\'entiers (<code>texts_to_sequences</code>). <a href="#dl-tokenization">Modélisation ▸ Tokenization — du texte aux entiers</a>'},
  {t:"Tool Calling (Function Calling)", d:'traduit une requête en langage naturel en appel de fonction avec les bons arguments — le LLM identifie QUOI appeler, il n\'exécute rien lui-même. <a href="#dl-tool-calling">Industrialisation ▸ Tool Calling (Function Calling)</a>'},
  {t:"Top-k / Top-p", d:'limitent les tokens candidats à la génération suivante — Top-k = les k plus probables ; Top-p (nucleus sampling) = les plus probables jusqu\'à cumuler une probabilité p. <a href="#dl-transformer-generation-params">Modélisation ▸ Contrôler la génération — Temperature, Top-k, Top-p</a>'},
  {t:"TPU (Tensor Processing Unit)", d:'accélérateur de calcul propriétaire Google, spécifique à GCP, optimisé pour le calcul matriciel massif du Deep Learning (surtout TensorFlow/JAX) — alternative au GPU, écosystème logiciel plus restreint. <a href="#infra-cloud-gcp">Industrialisation ▸ GCP</a>'},
  {t:"Train/Test Split", d:'séparation des données en un ensemble d\'entraînement et un ensemble de test, pour évaluer la capacité de généralisation. <a href="#wf0-split">Modélisation ▸ Workflow ML — Séparer train/test</a>'},
  {t:"Transfer Learning", d:'réutilise les couches de convolution d\'un modèle pré-entraîné (freezées) pour un nouveau problème, en ne ré-entraînant que de nouvelles couches Dense adaptées à la tâche. <a href="#dl-cnn-transfer-learning">Modélisation ▸ Architecture typique &amp; Transfer Learning</a>'},
  {t:"Transformer", d:'architecture qui traite toute une séquence EN PARALLÈLE via un mécanisme d\'attention, sans état interne séquentiel — à la base des LLM actuels. <a href="#dl-transformer-why">Modélisation ▸ Pourquoi remplacer le RNN — les limites du traitement séquentiel</a>'},
  {t:"TruncatedSVD", d:'réduction de dimension équivalente à PCA mais SANS centrer les données — utilisable directement sur une matrice creuse (comptage de mots, notes utilisateurs). <a href="#ml-recommender-systems">Modélisation ▸ Systèmes de recommandation</a>'},
  {t:"Underfitting (sous-apprentissage)", d:'le modèle est trop simple pour capter les patterns des données — scores train ET test bas. <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"Universal Approximation Theorem", d:'un réseau dense avec une seule couche cachée peut en théorie approximer n\'importe quelle fonction continue — ne garantit PAS qu\'on puisse facilement trouver ces paramètres optimaux. <a href="#dl-training-loss-optim">Modélisation ▸ Entraînement — loss &amp; optimizer</a>'},
  {t:"Vanishing Gradient", d:'lors de la backpropagation, le gradient rétrécit à mesure qu\'il remonte vers les premières couches — celles-ci apprennent donc plus lentement que les dernières. <a href="#dl-backpropagation">Modélisation ▸ Forward &amp; Backward Propagation</a>'},
  {t:"Variable aléatoire", d:'formalise le passage d\'une issue qualitative (ex: "pile") à une valeur numérique manipulable (ex: 1). <a href="#variable-aleatoire">Maths ▸ Variable aléatoire</a>'},
  {t:"Variance", d:'sensibilité du modèle au bruit des données d\'entraînement — une variance élevée signale un modèle trop complexe (overfitting). <a href="#ml-bias-variance">Modélisation ▸ Bias/Variance tradeoff</a>'},
  {t:"Variance (dispersion statistique)", d:'mesure la dispersion des données autour de la moyenne, en unités au carré — à ne pas confondre avec la Variance du Bias/Variance tradeoff (overfitting d\'un modèle). <a href="#stats-descriptives">Maths ▸ Statistiques descriptives</a>'},
  {t:"Vector Database", d:'base de données spécialisée qui stocke des embeddings (vecteurs) et leurs métadonnées, interrogeable par similarité — ex: Chroma. <a href="#dl-rag-pipeline">Industrialisation ▸ Pipeline RAG — Embedding, Vector Database, Retrieval</a>'},
  {t:"Vectorizing (NLP)", d:'conversion de texte préprocessé en représentation numérique (Bag-of-Words, Tf-idf...), seule forme exploitable par un modèle ML. <a href="#nlp-vectorizing">Modélisation ▸ Vectorizing</a>'},
  {t:"VIF (Variance Inflation Factor)", d:'mesure de multicolinéarité entre features, détecte les redondances qu\'une simple matrice de corrélation ne voit pas. <a href="#ml-multicollinearity">Maths ▸ Multicolinéarité — VIF</a>'},
  {t:"Word2Vec", d:'entraîne un embedding indépendant de la tâche, en prédisant un mot à partir de ses voisins (la fenêtre) — rapide à entraîner, à privilégier sur un petit corpus. <a href="#dl-nlp-word2vec">Modélisation ▸ Embedding indépendant de la tâche — Word2Vec</a>'},
  {t:"XGBoost", d:'implémentation dédiée et très optimisée du gradient boosting, avec early stopping via un jeu de validation dédié. <a href="#ml-ensemble-methods">Modélisation ▸ Ensemble Methods</a>'},
];
